import React, { useState } from 'react';
import './Cart.css';

const Cart = () => {
  // Sample initial cart state (replace with Context API / props later)
  const [cartItems, setCartItems] = useState([
    {
      id: 1,
      name: "Flagship Smartphone 12GB RAM",
      price: 699,
      quantity: 1,
      image: "https://via.placeholder.com/80"
    },
    {
      id: 2,
      name: "Wireless Noise-Canceling Earbuds",
      price: 149,
      quantity: 2,
      image: "https://via.placeholder.com/80"
    }
  ]);

  const updateQuantity = (id, amount) => {
    setCartItems(prev =>
      prev.map(item => {
        if (item.id === id) {
          const newQty = item.quantity + amount;
          return newQty > 0 ? { ...item, quantity: newQty } : item;
        }
        return item;
      })
    );
  };

  const removeItem = (id) => {
    setCartItems(prev => prev.filter(item => item.id !== id));
  };

  const subtotal = cartItems.reduce((acc, item) => acc + item.price * item.quantity, 0);
  const shippingFee = subtotal > 0 ? 15 : 0;
  const total = subtotal + shippingFee;

  return (
    <div className="cart-container">
      <h2>Your Shopping Cart</h2>

      {cartItems.length === 0 ? (
        <div className="cart-empty">
          <p>Your cart is currently empty.</p>
        </div>
      ) : (
        <div className="cart-content">
          {/* Left Column: Cart Items List */}
          <div className="cart-items-list">
            <div className="cart-header">
              <span>Product</span>
              <span>Price</span>
              <span>Quantity</span>
              <span>Total</span>
              <span>Remove</span>
            </div>
            <hr />

            {cartItems.map(item => (
              <React.Fragment key={item.id}>
                <div className="cart-item">
                  <div className="cart-product-info">
                    <img src={item.image} alt={item.name} />
                    <p>{item.name}</p>
                  </div>
                  <div className="cart-price">${item.price}</div>
                  <div className="cart-quantity">
                    <button onClick={() => updateQuantity(item.id, -1)}>-</button>
                    <span>{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.id, 1)}>+</button>
                  </div>
                  <div className="cart-total">${item.price * item.quantity}</div>
                  <button className="cart-remove-btn" onClick={() => removeItem(item.id)}>
                    ✕
                  </button>
                </div>
                <hr />
              </React.Fragment>
            ))}
          </div>

          {/* Right Column: Summary Box */}
          <div className="cart-summary">
            <h3>Order Summary</h3>
            <div className="summary-row">
              <span>Subtotal</span>
              <span>${subtotal}</span>
            </div>
            <div className="summary-row">
              <span>Shipping Fee</span>
              <span>${shippingFee}</span>
            </div>
            <hr />
            <div className="summary-row total-row">
              <span>Total</span>
              <span>${total}</span>
            </div>
            <button className="checkout-btn">PROCEED TO CHECKOUT</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Cart;
